import asyncio,json,subprocess
from pathlib import Path
import edge_tts
from PIL import Image
root=Path(__file__).resolve().parents[2]/'muzei/pervoprohodcy/nikitin'
texts=[
('Река и дорога','Посмотри на реку. В нашей истории она работает как дорога между городами. Никитин начинает с торговой поездки. Попробуй мысленно убрать с карты государственные границы нашего времени. Перед тобой цепочка владений, где нужны грамоты, разрешения и попутчики. В Нижнем Новгороде купец ждёт посольство две недели. Пока оно не пришло, дальше он не плывёт. Теперь открой первую остановку маршрута. Как много в таком путешествии зависит от людей, которых ты ещё не встретил.'),
('Потеря товара','Найди низовья Волги. Здесь исчезает то, ради чего купец отправился в путь: его товар. Но рассказ не заканчивается. Сначала Никитин хлопочет об освобождении спутников. Потом люди расходятся. Обрати внимание: возвращение домой доступно не всем одинаково. У одного там осталось имущество, у другого долги. Когда дойдёшь до игры, попробуй выбрать дорогу после потери товара. А затем сравни своё решение с документом. У нас есть возможность начать заново. У путешественника такой кнопки не было.'),
('Море и конь','На фотографии Ормуза виден берег. Для купца это граница двух способов двигаться: позади сухопутные переходы, впереди морское судно. Он берёт с собой коня. Представь не экзотическую прогулку, а необходимость кормить и сохранять животное в дороге. На карту поставлена надежда снова торговать. Теперь взгляни на старую карту мира. Южная сторона расположена сверху. Даже привычка смотреть на карту оказывается исторической. Мир не изменился от поворота листа, изменился твой способ его читать.'),
('Взгляд в обе стороны','Остановись у Бидара. Мы показываем современную фотографию, а не обещаем восстановить каждый камень пятнадцатого века. Никитин замечал людей, одежду, еду, торговлю. И сам вызывал любопытство. Когда читаешь путешественника, попробуй поменять направление взгляда: что видели в нём жители незнакомого города? Далёкая страна состояла из людей со своей повседневной жизнью. Это простое действие помогает услышать документ лучше, чем перечень названий.'),
('Память о доме','Представь, что рядом некому подсказать дату праздника, по которому ты привык считать год. Никитин пытается восстановить свой календарь. Мы часто говорим о расстояниях в путешествии. Здесь расстояние стало потерей привычного времени. На странице есть раздел с голосом документа. Открой вопрос о Руси. Вслушайся в то, как интерес к другим землям соединяется с памятью о своей. Одно чувство не обязательно вытесняет другое.'),
('Дорога записок','Последняя остановка принадлежит тетрадям. Они добрались до Москвы, когда автора уже не было в живых. Посмотри на старое печатное издание. Между ним и путешественником стоят переписчики, читатели, исследователи. Каждый мог оборвать эту цепочку; каждый, кто сохранил текст, продлил её. В конце игры выбери, что стоит записать в дорожную тетрадь. Путешествие оставляет знание не само собой. Кто-то должен заметить, различить и передать увиденное.')]
film='Он вышел из Твери с товаром. До Индии дошёл после ограбления. Между этими точками — реки, чужие города и море, которое нельзя перейти пешком. Он вёз коня, считал расходы, присматривался к людям. И записывал. Как живут. Чем торгуют. Во что верят. Как далеко осталась Русь. Когда он повернул домой, дорога снова оказалась сильнее человека. Никитин умер, не дойдя до Смоленска. Его тетради купцы привезли в Москву. Три моря разделили начало и конец путешествия. Несколько сохранённых страниц соединили его с нами.'
async def make():
 for i,(title,t) in enumerate(texts+[('Ролик',film)]):
  p=root/f'voice-{i}.mp3'
  if not p.exists():await edge_tts.Communicate(t,'ru-RU-DmitryNeural',rate='+0%').save(str(p))
  print('voice',i,flush=True)
asyncio.run(make())
stops=[];at=0
for i,(title,t) in enumerate(texts):
 stops.append({'t':round(at,2),'mark':f'{int(at)//60}:{int(at)%60:02d}','title':title});at+=float(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','csv=p=0',str(root/f'voice-{i}.mp3')]))
(root/'concat.txt').write_text(''.join(f"file 'voice-{i}.mp3'\n" for i in range(6)))
subprocess.run(['ffmpeg','-y','-v','error','-f','concat','-safe','0','-i',str(root/'concat.txt'),'-c','copy',str(root/'audioguide.mp3')],check=True)
json.dump({'stops':stops,'transcript':['<p>'+t+'</p>' for _,t in texts],'duration':at,'film':film},open(root/'audio.json','w'),ensure_ascii=False,indent=2)
# retain 5037px detail, reduce transfer without inventing pixels
im=Image.open(root/('atlas.jpg' if (root/'atlas.jpg').exists() else 'atlas-detail.jpg'));im.save(root/'atlas-detail.jpg',quality=84,optimize=True)
for p in root.glob('*.jpg'):
 if p.name in ['atlas.jpg','atlas-detail.jpg']:continue
 im=Image.open(p).convert('RGB');im.thumbnail((1600,1300));im.save(p,quality=85,optimize=True)
print('audio and images complete',flush=True)
